# Generated by build.py from recipe.yml for recipe socks5-relay-through-a-socks-proxy. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://localhost:8080/', 'socks5h://127.0.0.1:8081/', '-v', '--log-file', 'socks.log' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -x socks5h://127.0.0.1:8081 http://localhost:8080/hello.txt } finally { Stop-Process $server0 }
